def dien_khoa_yeu_cau_cu(apps, schema_editor):
    from psycopg import sql

    with schema_editor.connection.cursor() as con_tro:
        for bang in BANG_CO_KHOA_YEU_CAU:
            con_tro.execute(
                sql.SQL(
                    "UPDATE {} SET khoa_yeu_cau = gen_random_uuid()::text WHERE khoa_yeu_cau IS NULL"
                ).format(sql.Identifier(bang))
            )


